insert into public.pathway_rungs (church_id,level,sort_order,rung_key,title_en,category,completion_source,trackable,published,meta) values
  (null,5,100,'book-why-men','Why Men Hate Going to Church','book','manual',false,true,'{"type": "📚 Book · Level 5 — Executive Leader", "title": "Why Men Hate Going to Church", "body": "<h3>About This Book</h3>\n    <p>David Murrow''s provocative study explores why the modern church unintentionally repels men — and what leaders can do to build a church culture where men are engaged, challenged, and growing.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The \"feminization\" of church culture over the past century</li>\n      <li>What men actually need from a church community</li>\n      <li>Risk, adventure, and mission as male discipleship drivers</li>\n      <li>Practical changes to preaching style, worship, and small groups</li>\n      <li>Building a church that is both welcoming AND challenging</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>Part 1: The Gender Gap — Why It Exists</li>\n      <li>Part 2: What Men Want from a Church</li>\n      <li>Part 3: How the Church Became Feminine</li>\n      <li>Part 4: What You Can Do About It</li>\n      <li>Part 5: The Man-Friendly Church</li>\n    </ul>\n    <h3>Application</h3>\n    <p>Relevant to the Executive Leader who shapes church culture. Use its diagnostic questions in your leadership team retreat to honestly assess how welcoming your church is to men across all demographics.</p>", "footer": "David Murrow · Thomas Nelson", "source": "multiply-template"}'::jsonb),
  (null,5,101,'book-spiritual-leadership','Spiritual Leadership','book','manual',false,true,'{"type": "📚 Book · Level 5 — Executive Leader", "title": "Spiritual Leadership", "body": "<h3>About This Book</h3>\n    <p>J. Oswald Sanders'' classic — required reading for anyone aspiring to senior spiritual leadership. It defines the non-negotiable character qualities of a leader who leads by divine authority, not merely human ability.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The distinction between natural and spiritual leadership</li>\n      <li>The indispensable role of prayer and the Word</li>\n      <li>The cost and sacrifices of spiritual leadership</li>\n      <li>Time, vision, wisdom, and decision-making</li>\n      <li>Finishing well — the test of true leadership</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>Part 1: The Marks of a Spiritual Leader</li>\n      <li>Part 2: The Requirements of Leadership</li>\n      <li>Part 3: Qualities That Make or Break a Leader</li>\n      <li>Part 4: The Problems of Leadership</li>\n      <li>Part 5: The Cost of Leadership</li>\n      <li>Part 6: Leaders Worth Following</li>\n    </ul>\n    <h3>Application</h3>\n    <p>Pair with an annual personal retreat. Read slowly — one chapter per week. Journal responses to Sanders'' probing questions about your own leadership motives and spiritual condition.</p>", "footer": "J. Oswald Sanders · Moody Publishers · Classic text, multiple editions", "source": "multiply-template"}'::jsonb),
  (null,5,102,'book-making-leader','The Making of a Leader','book','manual',false,true,'{"type": "📚 Book · Level 5 — Executive Leader", "title": "The Making of a Leader", "body": "<h3>About This Book</h3>\n    <p>J. Robert Clinton''s landmark work on leadership development over a lifetime. Based on his study of hundreds of biblical and historical leaders, Clinton identifies the stages God uses to form leaders — including the critical role of \"processing\" through trials.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The six phases of a leader''s development journey</li>\n      <li>How God uses sovereign circumstances to shape character</li>\n      <li>\"Processing\" events — how to recognize and respond to them</li>\n      <li>The concept of \"convergence\" — your most fruitful years</li>\n      <li>Finishing well and leaving a legacy</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>1. God''s Perspective on Leadership Development</li>\n      <li>2. Phase 1 — Sovereign Foundations</li>\n      <li>3. Phase 2 — Inner Life Growth</li>\n      <li>4. Phase 3 — Ministry Maturing</li>\n      <li>5. Phase 4 — Life Maturing</li>\n      <li>6. Phase 5 — Convergence</li>\n      <li>7. Phase 6 — Afterglow / Legacy</li>\n      <li>8. Processing Events and Their Meaning</li>\n    </ul>\n    <h3>Application</h3>\n    <p>Executive leaders should use this to map their own leadership timeline and identify what season they are in. Also invaluable for coaching younger leaders through trials.</p>", "footer": "J. Robert Clinton · NavPress", "source": "multiply-template"}'::jsonb),
  (null,5,103,'book-christian-coaching','Christian Coaching (Christian Coaching)','book','manual',false,true,'{"type": "📚 Book · Level 5 — Executive Leader", "title": "Christian Coaching: Helping Others Turn Potential into Reality", "body": "<h3>About This Book</h3>\n    <p>Gary Collins'' definitive guide to coaching from a Christian perspective. Essential for executive leaders who must develop, release, and coach other leaders rather than doing all the ministry themselves.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>What coaching is — and is not (vs. counseling, mentoring, consulting)</li>\n      <li>The GROW model adapted for Christian ministry contexts</li>\n      <li>Asking powerful questions that unlock potential</li>\n      <li>Listening at a deeper level</li>\n      <li>Coaching leaders through transitions and challenges</li>\n      <li>The coach''s own spiritual formation</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>Part 1: Understanding Christian Coaching</li>\n      <li>Part 2: The Core Coaching Skills</li>\n      <li>Part 3: Coaching in Special Situations</li>\n      <li>Part 4: Building a Coaching Practice</li>\n    </ul>", "footer": "Gary Collins · NavPress · 2nd Edition", "source": "multiply-template"}'::jsonb),
  (null,5,104,'train-apiis-masters','APIIS Masters Program','training','manual',false,true,'{"type": "🎯 Training · Level 5 — Executive Leader", "title": "APIIS Masters Program", "body": "<h3>Overview</h3>\n    <p>The Asia Pacific International Institute of Innovative Scholarship (APIIS) Masters Program is an advanced theological education track designed for senior ministry leaders. It combines rigorous academic theology with practical ministry application in the Asian church context.</p>\n    <h3>Areas of Study</h3>\n    <ul>\n      <li>Biblical Studies — Old and New Testament in depth</li>\n      <li>Systematic Theology — doctrine for ministry application</li>\n      <li>Homiletics — advanced preaching theory and practice</li>\n      <li>Church Leadership and Administration</li>\n      <li>Missiology — Asian and global missions frameworks</li>\n      <li>Pastoral Care and Counseling</li>\n      <li>Christian Education and Curriculum Development</li>\n    </ul>\n    <h3>Who It''s For</h3>\n    <p>Executive Leaders and senior Coach-level leaders who want formal theological grounding for their ministry leadership. Particularly recommended for those in preaching and teaching roles or those heading toward church planting.</p>", "footer": "APIIS · Asia Pacific International Institute of Innovative Scholarship · Verify current program details with Pastor", "source": "multiply-template"}'::jsonb),
  (null,5,105,'train-ccf-hope','CCF Glorious Hope','training','manual',false,true,'{"type": "🎯 Training · Levels 4 & 5", "title": "CCF Glorious Hope Program", "body": "<h3>Overview</h3>\n    <p>Christ''s Commission Fellowship''s Glorious Hope is a comprehensive Christian living and leadership formation program that has equipped thousands of Filipino believers. It combines biblical teaching, small group community, and life application tracks across multiple levels.</p>\n    <h3>Program Tracks</h3>\n    <ul>\n      <li><strong>Track 1: Knowing God</strong> — Foundations of Christian faith and life</li>\n      <li><strong>Track 2: Growing in Christ</strong> — Spiritual disciplines and character formation</li>\n      <li><strong>Track 3: Serving the Church</strong> — Discovering and using spiritual gifts in community</li>\n      <li><strong>Track 4: Reaching the World</strong> — Evangelism, missions, and disciple-making</li>\n    </ul>\n    <h3>Why It''s in the Pipeline</h3>\n    <p>CCF Glorious Hope provides exposure to one of the most effective discipleship systems in the Philippine church. Leaders who experience it return with best practices, fresh language, and a broader perspective on what discipleship culture can look like.</p>", "footer": "Christ\\''s Commission Fellowship · CCF · ccf.ph (verify link with Pastor)", "source": "multiply-template"}'::jsonb),
  (null,5,106,'btli-106','BTLI 106','lesson','manual',false,true,'{"type": "🎓 BTLI Module · Level 5 — Executive Leader", "title": "BTLI 106: Leading the Whole Church", "body": "<h3>Course Overview</h3>\n    <p>BTLI 106 is the capstone module of the entire BTLI track — a senior leadership formation experience for those God is calling to lead the whole church or plant a new one. It is as much a spiritual formation intensive as it is a leadership training course.</p>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>Session 1: The Senior Leader''s Calling — Are You Sure?</li>\n      <li>Session 2: Vision — Receiving, Clarifying, and Communicating God''s Vision</li>\n      <li>Session 3: Organizational Culture — What It Is and How You Shape It</li>\n      <li>Session 4: Managing the Full Leadership Pipeline</li>\n      <li>Session 5: Board Governance and Elder Leadership</li>\n      <li>Session 6: The Public Ministry — Preaching, Presence, and Platform</li>\n      <li>Session 7: Church Finances and Stewardship at the Organizational Level</li>\n      <li>Session 8: Church Planting — Releasing What God Has Built</li>\n      <li>Session 9: Crisis Leadership — When Everything Falls Apart</li>\n      <li>Session 10: The Senior Leader''s Marriage and Family</li>\n      <li>Session 11: Succession — Your Greatest Leadership Act</li>\n      <li>Session 12: The Examined Leader — A 360° Assessment and Life Plan</li>\n    </ul>\n    <h3>Format</h3>\n    <p>12 sessions, 2 hours each. Requires completion of BTLI 101–105. Culminates in a personal leadership development plan and a 360° assessment reviewed by the senior pastor and elders. Not a lecture series — a guided formation experience.</p>", "footer": "BTLI · Bible Training and Leadership Institute · Your Church", "source": "multiply-template"}'::jsonb),
  (null,5,107,'assess-360-elder','360° Elder Evaluation','assessment','manual',false,true,'{"type": "📋 Assessment · Level 5 — Executive Leader", "title": "360° Elder Evaluation", "body": "<h3>Purpose</h3>\n    <p>A comprehensive annual evaluation of the Executive Leader''s leadership health, gathered from multiple perspectives — elder board, senior staff, key volunteers, and select church members. Based on the 1 Timothy 3 and Titus 1 qualifications for elder/overseer.</p>\n    <h3>Evaluation Dimensions</h3>\n    <ul>\n      <li><strong>Biblical qualifications:</strong> \"Above reproach\" — assessed across home, church, and community</li>\n      <li><strong>Relational health:</strong> Spouse/family testimony; team culture feedback</li>\n      <li><strong>Spiritual vitality:</strong> Prayer life, Word engagement, accountability faithfulness</li>\n      <li><strong>Leadership effectiveness:</strong> Vision clarity, decision quality, team development</li>\n      <li><strong>Financial integrity:</strong> Personal stewardship and organizational financial oversight</li>\n      <li><strong>Emotional health:</strong> EQ, conflict handling, self-awareness</li>\n    </ul>\n    <h3>Process</h3>\n    <p>Annual. 360° survey sent to 15–20 raters. Results compiled by an outside facilitator (to ensure honesty) and debriefed in a 2-hour session with the Elder Board. Developmental goals set for the next 12 months.</p>", "footer": "Your Church · Elder Board · Annual · Confidential", "source": "multiply-template"}'::jsonb),
  (null,5,108,'assess-church-health','Church Health Survey','assessment','manual',false,true,'{"type": "📋 Assessment · Level 5 — Executive Leader", "title": "Church Health Survey", "body": "<h3>Purpose</h3>\n    <p>An annual congregational health survey measuring the church''s vitality across the key dimensions of a healthy, multiplying church. Provides the Executive Leader with data-driven insight to guide strategic decisions.</p>\n    <h3>Dimensions Measured</h3>\n    <ul>\n      <li><strong>Discipleship depth:</strong> Are members growing in Christ-likeness?</li>\n      <li><strong>Community health:</strong> Are genuine, caring relationships happening?</li>\n      <li><strong>Evangelism effectiveness:</strong> Is the church growing through conversion?</li>\n      <li><strong>Worship authenticity:</strong> Is corporate worship life-giving and God-honoring?</li>\n      <li><strong>Generosity:</strong> Is the congregation growing in financial stewardship?</li>\n      <li><strong>Multiplication culture:</strong> Are people intentionally discipling others?</li>\n      <li><strong>Leadership pipeline health:</strong> Is the pipeline producing leaders at every level?</li>\n    </ul>\n    <h3>Format</h3>\n    <p>Anonymous 40-question survey distributed to all members annually. Results presented to the Elder Board and shared transparently with the congregation (aggregated, not individual). Used to set the church''s annual ministry priorities.</p>", "footer": "Your Church · Church Health Survey · Annual", "source": "multiply-template"}'::jsonb),
  (null,5,109,'ref-character-love','Love','character','manual',false,true,'{}'::jsonb),
