  (null,5,113,'habit-spiritual-director','Weekly Spiritual Director','discipline','manual',false,true,'{"type": "🌿 Accountability · Level 5 — Executive Leader", "title": "Weekly Spiritual Director Meeting", "body": "<h3>What Is Spiritual Direction?</h3>\n    <p>Spiritual direction is an ancient Christian practice in which a more experienced believer helps another person attend to God''s presence and activity in their life. Unlike counseling (which fixes problems) or coaching (which develops skills), spiritual direction is about noticing where God is moving and responding faithfully.</p>\n    <h3>Who the Spiritual Director Is</h3>\n    <p>For an Executive Leader, the spiritual director should be: someone outside your immediate ministry context, spiritually mature and prayerful, trained in the practice of spiritual direction, and someone you respect enough to be completely honest with.</p>\n    <h3>What Happens in a Session</h3>\n    <ul>\n      <li>Opening silence and prayer (10 min)</li>\n      <li>Director asks: \"Where have you noticed God this week?\"</li>\n      <li>Leader shares; director listens and asks gentle questions</li>\n      <li>Reflection on a Scripture passage (if appropriate)</li>\n      <li>Closing prayer together</li>\n    </ul>\n    <h3>Duration</h3>\n    <p>60–90 minutes, monthly (not weekly for most). The term \"weekly\" in the pipeline reflects frequency of personal prayer reflection that prepares for the monthly direction session.</p>", "footer": "Practice of Spiritual Direction · Recommended: Monthly with a trained director", "source": "multiply-template"}'::jsonb),
  (null,5,114,'habit-board-accountability','Monthly Board Accountability','discipline','manual',false,true,'{}'::jsonb),
  (null,5,115,'habit-annual-retreat','Annual Personal Retreat','discipline','manual',false,true,'{}'::jsonb),
