  (null,5,123,'ref-competency-crisis-leadership','Crisis leadership','competency','manual',false,true,'{}'::jsonb),
  (null,5,124,'coach-executive','Executive Coach (monthly)','coaching','manual',false,true,'{}'::jsonb),
  (null,5,125,'coach-lencioni','Team Health Review (Lencioni)','coaching','manual',false,true,'{}'::jsonb),
  (null,5,126,'lifedev-sabbath','Sabbath Rhythm Plan','coaching','manual',false,true,'{}'::jsonb),
  (null,5,127,'lifedev-mission','Personal Mission Statement','coaching','manual',false,true,'{}'::jsonb),
  (null,4,128,'book-leadership-coaching','Leadership Coaching (Stoltzfus)','book','manual',false,true,'{"type": "📚 Book · Level 4 — Director", "title": "Leadership Coaching", "body": "<h3>About This Book</h3>\n    <p>Tony Stoltzfus'' practical guide for leaders who coach other leaders. One of the most hands-on coaching books available, with specific question frameworks and real coaching dialogue examples.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The coaching conversation structure</li>\n      <li>Transformational questioning techniques</li>\n      <li>Identifying and working with leader values and beliefs</li>\n      <li>Coaching through obstacles and limiting beliefs</li>\n      <li>Goal-setting and accountability frameworks</li>\n      <li>Building a sustainable coaching rhythm</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>Part 1: What Coaching Is</li>\n      <li>Part 2: Core Coaching Skills</li>\n      <li>Part 3: The Coaching Conversation</li>\n      <li>Part 4: Advanced Coaching Techniques</li>\n      <li>Part 5: Coaching Special Situations</li>\n    </ul>", "footer": "Tony Stoltzfus · Coach22 Bookstore", "source": "multiply-template"}'::jsonb),
  (null,4,129,'book-disciplines-coach','Disciplines of a Christian Coach (Webb)','book','manual',false,true,'{"type": "📚 Book · Level 4 — Director", "title": "The Disciplines, Skills, and Heart of a Christian Coach", "body": "<h3>About This Book</h3>\n    <p>Keith E. Webb''s comprehensive guide to Christian coaching competencies. Webb is founder of Creative Results Management and has trained thousands of coaches worldwide. This book integrates spiritual formation with practical coaching skills.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The COACH model (Connect, Outcome, Awareness, Course, Highlights)</li>\n      <li>Listening as a spiritual discipline</li>\n      <li>Asking questions that create movement</li>\n      <li>The coach''s own spiritual health as a prerequisite</li>\n      <li>Coaching in cross-cultural contexts</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>1. The Heart of a Coach</li>\n      <li>2. The COACH Model Explained</li>\n      <li>3. Listening Skills for Coaches</li>\n      <li>4. Powerful Questions</li>\n      <li>5. Creating Awareness</li>\n      <li>6. Designing Action Plans</li>\n      <li>7. Accountability in Coaching</li>\n    </ul>", "footer": "Keith E. Webb · Active Results LLC", "source": "multiply-template"}'::jsonb),
  (null,4,130,'book-advantage','The Advantage (Lencioni)','book','manual',false,true,'{"type": "📚 Book · Level 4 — Director", "title": "The Advantage: Why Organizational Health Trumps Everything Else", "body": "<h3>About This Book</h3>\n    <p>Patrick Lencioni''s argument that organizational health — not strategy, finances, or technology — is the greatest competitive advantage. Directly applicable to ministry departments that want sustainable fruit.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The Four Disciplines of Organizational Health</li>\n      <li>Building a cohesive leadership team</li>\n      <li>Creating organizational clarity</li>\n      <li>Overcommunicating clarity to the whole team</li>\n      <li>Reinforcing clarity through human systems</li>\n      <li>The role of meetings in a healthy organization</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>Discipline 1: Build a Cohesive Leadership Team</li>\n      <li>Discipline 2: Create Clarity</li>\n      <li>Discipline 3: Overcommunicate Clarity</li>\n      <li>Discipline 4: Reinforce Clarity</li>\n      <li>The Role of Meetings</li>\n    </ul>", "footer": "Patrick Lencioni · Jossey-Bass", "source": "multiply-template"}'::jsonb),
  (null,4,131,'train-idc-coaching','Coaching Certification (IDC)','training','manual',false,true,'{"type": "🎯 Training · Level 4 — Director", "title": "IDC Coaching Certification", "body": "<h3>Overview</h3>\n    <p>The IDC Coaching Certification program trains ministry leaders in the professional and biblical competencies of coaching — equipping them to develop the leaders under their care through intentional one-on-one coaching conversations, not just directive management.</p>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>The difference between coaching, mentoring, counseling, and consulting</li>\n      <li>Core coaching competencies (ICF-aligned, contextualized for ministry)</li>\n      <li>The GROW model in ministry coaching</li>\n      <li>Listening, questioning, and reflecting skills</li>\n      <li>Coaching through transitions and challenges</li>\n      <li>Building a coaching culture in your ministry</li>\n    </ul>", "footer": "IDC · International Discipleship and Church Planting", "source": "multiply-template"}'::jsonb),
  (null,4,132,'train-biblical-counseling','Biblical Counseling Level 1','training','manual',false,true,'{"type": "🎯 Training · Level 4 — Director", "title": "Biblical Counseling Level 1", "body": "<h3>Overview</h3>\n    <p>A foundational course in biblical counseling equipping Directors and senior leaders to provide basic pastoral care and counseling from a Scripture-based framework — and to know when to refer to professional counselors.</p>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>The sufficiency of Scripture for life and ministry challenges</li>\n      <li>The relationship between biblical counseling and psychology</li>\n      <li>The counseling conversation: listening, understanding, and responding</li>\n      <li>Common presenting problems: anxiety, grief, marriage conflict, addiction</li>\n      <li>When to refer — recognizing the limits of pastoral care</li>\n      <li>Confidentiality and ethical guidelines</li>\n      <li>Developing a care network in the local church</li>\n    </ul>", "footer": "ACBC-affiliated or local equivalent · Verify with Pastor for specific program provider", "source": "multiply-template"}'::jsonb),
  (null,4,133,'train-ccf-hope','CCF Glorious Hope','training','manual',false,true,'{"type": "🎯 Training · Levels 4 & 5", "title": "CCF Glorious Hope Program", "body": "<h3>Overview</h3>\n    <p>Christ''s Commission Fellowship''s Glorious Hope is a comprehensive Christian living and leadership formation program that has equipped thousands of Filipino believers. It combines biblical teaching, small group community, and life application tracks across multiple levels.</p>\n    <h3>Program Tracks</h3>\n    <ul>\n      <li><strong>Track 1: Knowing God</strong> — Foundations of Christian faith and life</li>\n      <li><strong>Track 2: Growing in Christ</strong> — Spiritual disciplines and character formation</li>\n      <li><strong>Track 3: Serving the Church</strong> — Discovering and using spiritual gifts in community</li>\n      <li><strong>Track 4: Reaching the World</strong> — Evangelism, missions, and disciple-making</li>\n    </ul>\n    <h3>Why It''s in the Pipeline</h3>\n    <p>CCF Glorious Hope provides exposure to one of the most effective discipleship systems in the Philippine church. Leaders who experience it return with best practices, fresh language, and a broader perspective on what discipleship culture can look like.</p>", "footer": "Christ\\''s Commission Fellowship · CCF · ccf.ph (verify link with Pastor)", "source": "multiply-template"}'::jsonb),
  (null,4,134,'train-conflict','Conflict Resolution Workshop','training','manual',false,true,'{"type": "🎯 Training · Level 4 — Director", "title": "Conflict Resolution Workshop", "body": "<h3>Overview</h3>\n    <p>A practical one-day or two-day workshop equipping Directors to handle the inevitable interpersonal and ministry conflicts that arise when leading a team. Based on peacemaking principles from Ken Sande''s <em>The Peacemaker</em> and adapted for Filipino ministry contexts.</p>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>Why conflict is not the enemy — the biblical view of conflict as opportunity</li>\n      <li>The four \"G\"s of biblical peacemaking (Glorify God, Get the log out, Gently restore, Go and be reconciled)</li>\n      <li>Conflict styles — understanding your default response</li>\n      <li>The Matthew 18 process in a local church context</li>\n      <li>Mediating conflict between two other parties</li>\n      <li>Filipino-specific challenges: \"hiya,\" indirect communication, and avoiding \"tampo\"</li>\n    </ul>", "footer": "Based on The Peacemaker (Ken Sande) · Adapted for local church use", "source": "multiply-template"}'::jsonb),
  (null,4,135,'btli-105','BTLI 105','lesson','manual',false,true,'{"type": "🎓 BTLI Module · Level 4 — Director", "title": "BTLI 105: Directing a Ministry Department", "body": "<h3>Course Overview</h3>\n    <p>BTLI 105 is designed for leaders who are being developed for or have recently stepped into Director-level ministry leadership. It focuses on the systems, strategy, and soul required to lead an entire ministry department sustainably.</p>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>Session 1: The Director''s Scope — Owning a Whole Ministry Area</li>\n      <li>Session 2: Strategic Ministry Planning (Annual and Quarterly)</li>\n      <li>Session 3: Building and Managing a Ministry Budget</li>\n      <li>Session 4: Recruiting, Onboarding, and Releasing Volunteers</li>\n      <li>Session 5: Running Meetings That Actually Accomplish Something</li>\n      <li>Session 6: Conflict Resolution at the Leadership Level</li>\n      <li>Session 7: Data-Driven Ministry — Measuring What Matters</li>\n      <li>Session 8: Coaching Your Team of Leaders</li>\n      <li>Session 9: Communicating Vision Upward and Downward</li>\n      <li>Session 10: Ministry Health Assessment and Action Planning</li>\n      <li>Session 11: Counseling Basics for Ministry Leaders</li>\n      <li>Session 12: The Director''s Spiritual Health — Leading from Overflow</li>\n    </ul>\n    <h3>Format</h3>\n    <p>12 sessions, 90 minutes each. Includes a ministry health audit project and a strategic plan presentation to senior leadership as capstone requirements.</p>", "footer": "BTLI · Bible Training and Leadership Institute · Your Church", "source": "multiply-template"}'::jsonb),
  (null,4,136,'assess-ministry-health','Ministry Health Dashboard','assessment','manual',false,true,'{"type": "📋 Assessment · Level 4 — Director", "title": "Ministry Health Dashboard Review", "body": "<h3>Purpose</h3>\n    <p>A quarterly review of each ministry department''s health indicators — used by the Director in their coaching conversation with the Senior Pastor/Executive Leader. Provides objective data to complement subjective impressions.</p>\n    <h3>Dashboard Metrics</h3>\n    <ul>\n      <li><strong>Participation:</strong> Average attendance trend (monthly)</li>\n      <li><strong>Volunteer health:</strong> Retention rate, satisfaction, and burnout indicators</li>\n      <li><strong>Spiritual growth:</strong> Percentage of ministry participants in active discipleship</li>\n      <li><strong>New leaders:</strong> How many leaders were developed and promoted this quarter?</li>\n      <li><strong>Financial stewardship:</strong> Budget vs. actual; ministry ROI</li>\n      <li><strong>EOLO effectiveness:</strong> How many new people entered through this ministry?</li>\n      <li><strong>Fruit:</strong> Stories of life change from this quarter</li>\n    </ul>", "footer": "Your Church · Ministry Health Dashboard · Quarterly", "source": "multiply-template"}'::jsonb),
  (null,4,137,'assess-360-peer','360° Peer Feedback','assessment','manual',false,true,'{"type": "📋 Assessment · Level 4 — Director", "title": "360° Ministry Peer Feedback", "body": "<h3>Purpose</h3>\n    <p>A semi-annual peer feedback process for Director-level leaders — gathering input from those they lead, those they are led by, and their peers on the leadership team. Designed to surface blind spots and affirm genuine strengths.</p>\n    <h3>Feedback Areas</h3>\n    <ul>\n      <li>Vision communication clarity</li>\n      <li>Team development effectiveness</li>\n      <li>Meeting facilitation quality</li>\n      <li>Conflict handling and peacemaking</li>\n      <li>Accessibility and pastoral care for team members</li>\n      <li>Personal spiritual example and integrity</li>\n    </ul>\n    <h3>Process</h3>\n    <p>Survey sent to 8–12 raters. Debrief with the senior pastor. Written development goals filed in the leader''s pipeline record.</p>", "footer": "Your Church · Semi-annual · Confidential", "source": "multiply-template"}'::jsonb),
  (null,4,138,'assess-coaching-rubric','Coaching Competency Rubric','assessment','manual',false,true,'{"type": "📋 Assessment · Level 4 — Director", "title": "Coaching Competency Rubric", "body": "<h3>Purpose</h3>\n    <p>A behavioral rubric assessing a Director''s coaching effectiveness — specifically their ability to develop the leaders under their care through intentional coaching conversations and growth opportunities.</p>\n    <h3>Competency Areas</h3>\n    <ul>\n      <li><strong>Listening:</strong> Does the Director truly listen, or just wait to speak?</li>\n      <li><strong>Questioning:</strong> Do their questions open up new thinking or just seek information?</li>\n      <li><strong>Feedback:</strong> Is feedback specific, timely, and growth-oriented?</li>\n      <li><strong>Development planning:</strong> Does each leader under them have an active development plan?</li>\n      <li><strong>Accountability:</strong> Does the Director follow up on commitments made in coaching conversations?</li>\n      <li><strong>Celebration:</strong> Does the Director create a culture of recognizing wins?</li>\n    </ul>\n    <h3>Rating Scale</h3>\n    <p>1 (Not yet demonstrated) → 2 (Developing) → 3 (Consistently demonstrates) → 4 (Models for others)</p>", "footer": "Your Church · Coaching Competency Rubric · Quarterly review", "source": "multiply-template"}'::jsonb),
