  (null,4,155,'assess-strengths','CliftonStrengths Debrief','coaching','manual',false,true,'{"type": "📋 Assessment · Levels 3 & 4", "title": "CliftonStrengths Assessment", "body": "<h3>Overview</h3>\n    <p>Gallup''s CliftonStrengths (formerly StrengthsFinder) assessment identifies a person''s top 5 (or all 34) natural talent themes — the patterns of thought, feeling, and behavior that come most naturally to them and can be developed into genuine strengths.</p>\n    <h3>The 34 Themes (organized in 4 domains)</h3>\n    <ul>\n      <li><strong>Executing:</strong> Achiever, Arranger, Belief, Consistency, Deliberative, Discipline, Focus, Responsibility, Restorative</li>\n      <li><strong>Influencing:</strong> Activator, Command, Communication, Competition, Maximizer, Self-Assurance, Significance, Woo</li>\n      <li><strong>Relationship Building:</strong> Adaptability, Connectedness, Developer, Empathy, Harmony, Includer, Individualization, Positivity, Relational</li>\n      <li><strong>Strategic Thinking:</strong> Analytical, Context, Futuristic, Ideation, Input, Intellection, Learner, Strategic</li>\n    </ul>\n    <h3>Application in the Pipeline</h3>\n    <p>Results are debriefed in a 90-minute session with a CliftonStrengths-trained coach. The outcome: a strengths-based development plan that connects the person''s top themes to specific leadership competencies and ministry opportunities in the MULTIPLY pipeline.</p>", "footer": "Gallup · CliftonStrengths · gallup.com/cliftonstrengths", "source": "multiply-template"}'::jsonb),
  (null,4,156,'lifedev-reading-plan','Leadership Reading Plan','coaching','manual',false,true,'{}'::jsonb),
  (null,4,157,'lifedev-family-covenant','Family Priority Covenant','coaching','manual',false,true,'{}'::jsonb),
  (null,3,158,'book-mere-christianity','Mere Christianity','book','manual',false,true,'{"type": "📚 Book · Level 3 — Coach", "title": "Mere Christianity", "body": "<h3>About This Book</h3>\n    <p>C.S. Lewis'' masterful defense and explanation of the Christian faith. Essential for coaches who must be able to explain and defend the faith intelligently to the leaders they develop.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The moral argument for the existence of God</li>\n      <li>The core beliefs of Christianity explained plainly</li>\n      <li>Christian behavior: virtues and the \"great sin\" (pride)</li>\n      <li>What it means to be \"in Christ\" — new creation theology</li>\n      <li>The goal of the Christian life: becoming like Christ</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>Book 1: Right and Wrong as a Clue to the Meaning of the Universe</li>\n      <li>Book 2: What Christians Believe</li>\n      <li>Book 3: Christian Behavior</li>\n      <li>Book 4: Beyond Personality — or First Steps in the Doctrine of the Trinity</li>\n    </ul>", "footer": "C.S. Lewis · HarperOne · Originally broadcast as BBC radio talks, 1941–44", "source": "multiply-template"}'::jsonb),
  (null,3,159,'book-still-sovereign','Still Sovereign','book','manual',false,true,'{"type": "📚 Book · Level 3 — Coach", "title": "Still Sovereign: Contemporary Perspectives on Election, Foreknowledge, and Grace", "body": "<h3>About This Book</h3>\n    <p>Edited by Thomas Schreiner and Bruce Ware, this scholarly yet accessible collection defends the Reformed understanding of God''s sovereignty in salvation — equipping coaches to handle theological questions from the leaders they disciple.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>Divine sovereignty and human responsibility — holding both</li>\n      <li>Election, foreknowledge, and predestination in Scripture</li>\n      <li>Perseverance of the saints</li>\n      <li>How these doctrines affect pastoral care and counseling</li>\n      <li>The doxological purpose of Reformed soteriology</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>1. Does God Know the Future? (Ware)</li>\n      <li>2. Election and Free Will (Schreiner)</li>\n      <li>3. The New Birth: Regeneration Before Faith</li>\n      <li>4. Perseverance of the Saints</li>\n      <li>5. Pastoral Implications of God''s Sovereignty</li>\n    </ul>", "footer": "Schreiner & Ware (Eds.) · Baker Books", "source": "multiply-template"}'::jsonb),
  (null,3,160,'book-multiply','Multiply (Chan)','book','manual',false,true,'{"type": "📚 Book · Level 3 — Coach", "title": "Multiply: Disciples Making Disciples", "body": "<h3>About This Book</h3>\n    <p>Francis Chan''s practical discipleship guide, structured as a training manual for making disciples who make disciples. Ideal for coaches who are training leaders to replicate themselves.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The Great Commission as every believer''s mandate</li>\n      <li>What a disciple actually looks like</li>\n      <li>How to read and study the Bible for transformation</li>\n      <li>Living as the church — the community dimension of discipleship</li>\n      <li>The Old Testament story and its connection to the New</li>\n      <li>Practical tools for disciple-making conversations</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>Part 1: Living as a Disciple Maker</li>\n      <li>Part 2: Living as the Church</li>\n      <li>Part 3: How to Study the Bible</li>\n      <li>Part 4: The Old Testament</li>\n      <li>Part 5: The New Testament</li>\n    </ul>\n    <h3>Application</h3>\n    <p>Can be used as a discipleship curriculum — each section becomes a discussion guide for coach-to-leader one-on-ones.</p>", "footer": "Francis Chan & Mark Beuving · David C Cook", "source": "multiply-template"}'::jsonb),
  (null,3,161,'book-happy-lies','Happy Lies (Adams)','book','manual',false,true,'{"type": "📚 Book · Level 3 — Coach", "title": "Happy Lies", "body": "<h3>About This Book</h3>\n    <p>Ken Adams'' book exposing the comfortable falsehoods that keep Christians from genuine discipleship and leadership growth. Directly applicable to the Philippine church context where \"pakikisama\" and false peace can hinder honest accountability.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The \"happy lies\" Christians tell themselves and each other</li>\n      <li>How false comfort prevents authentic growth</li>\n      <li>The courage of honest accountability</li>\n      <li>Truth-telling in the context of Filipino relational culture</li>\n      <li>How coaches must confront lies gently but firmly</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>1. The Lie of Comfort</li>\n      <li>2. The Lie of Busyness</li>\n      <li>3. The Lie of Comparison</li>\n      <li>4. The Lie of Someday</li>\n      <li>5. The Truth That Sets Us Free</li>\n    </ul>\n    <h3>Note</h3>\n    <p>Please confirm page count and publisher details with Pastor for final bibliography. Content outline is based on Ken Adams'' discipleship teaching series.</p>", "footer": "Ken Adams · [Please confirm publisher details with Pastor]", "source": "multiply-template"}'::jsonb),
  (null,3,162,'train-preaching','Preaching Practicum','training','manual',false,true,'{"type": "🎯 Training · Level 3 — Coach", "title": "Preaching Practicum", "body": "<h3>Overview</h3>\n    <p>A supervised, feedback-intensive preaching lab for leaders stepping into regular teaching and preaching ministry. Not a lecture on homiletics — a practice environment where you preach and receive structured critique.</p>\n    <h3>Program Flow</h3>\n    <ul>\n      <li>Week 1–2: Review of expository preaching principles and sermon structure</li>\n      <li>Week 3: First practice sermon (10 minutes) — peer and coach feedback</li>\n      <li>Week 4: Second practice sermon (20 minutes) — with video review</li>\n      <li>Week 5: Full-length sermon (35–40 minutes) in a live service setting</li>\n      <li>Week 6: Debrief session using the Sermon Evaluation Rubric</li>\n    </ul>\n    <h3>Evaluation Criteria</h3>\n    <ul>\n      <li>Biblical accuracy and exegetical faithfulness</li>\n      <li>Clear structure and logical flow</li>\n      <li>Relevant and culturally appropriate illustrations</li>\n      <li>Clear application points</li>\n      <li>Delivery: voice, body language, eye contact, pace</li>\n      <li>Audience engagement</li>\n    </ul>", "footer": "Your Church · Preaching Practicum · Runs twice a year", "source": "multiply-template"}'::jsonb),
  (null,3,163,'train-idc-discipleship','Discipleship Coaching (IDC)','training','manual',false,true,'{"type": "🎯 Training · Level 3 — Coach", "title": "IDC Discipleship Coaching Intensive", "body": "<h3>Overview</h3>\n    <p>A focused IDC training specifically on discipleship coaching — how to walk alongside developing leaders and new disciples in a way that produces lasting transformation rather than surface-level compliance.</p>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>Jesus'' discipleship model — what He actually did</li>\n      <li>The 2 Timothy 2:2 multiplication principle in practice</li>\n      <li>How to structure a discipleship relationship</li>\n      <li>Asking the right questions at the right time</li>\n      <li>Handling common discipleship challenges</li>\n      <li>Knowing when to graduate a disciple</li>\n    </ul>", "footer": "IDC · International Discipleship and Church Planting", "source": "multiply-template"}'::jsonb),
  (null,3,164,'btli-104','BTLI 104','lesson','manual',false,true,'{"type": "🎓 BTLI Module · Level 3 — Coach", "title": "BTLI 104: Leading Leaders — The Coach Track", "body": "<h3>Course Overview</h3>\n    <p>BTLI 104 equips leaders who are ready to step into the Coach role — leading and developing other leaders rather than just ministry participants. This is the module where the multiplication mindset is truly activated.</p>\n    <h3>Learning Objectives</h3>\n    <ul>\n      <li>Conduct effective one-on-one coaching conversations with leaders</li>\n      <li>Lead a group leader huddle that sharpens leadership competencies</li>\n      <li>Provide feedback and evaluation that builds confidence, not fear</li>\n      <li>Identify and develop potential leaders from within the team</li>\n      <li>Guard the mission and values of the church at the team level</li>\n    </ul>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>Session 1: From Leader to Coach — The Hardest Shift in the Pipeline</li>\n      <li>Session 2: The Anatomy of a Great Coaching Conversation</li>\n      <li>Session 3: Asking Questions Like Jesus Did</li>\n      <li>Session 4: The Leader Huddle — Structure and Substance</li>\n      <li>Session 5: Giving Feedback That Changes Behavior</li>\n      <li>Session 6: Identifying Potential in Others</li>\n      <li>Session 7: Coaching Through Crisis and Conflict</li>\n      <li>Session 8: Designing a Development Plan for Your Leaders</li>\n      <li>Session 9: Preaching and Teaching Practicum</li>\n      <li>Session 10: The Coach''s Soul — Avoiding Burnout While Developing Others</li>\n    </ul>\n    <h3>Format</h3>\n    <p>10 sessions, 90 minutes each. Includes a live coaching practicum (Sessions 9–10) with peer feedback. A written leader development plan is required for module completion.</p>", "footer": "BTLI · Bible Training and Leadership Institute · Your Church", "source": "multiply-template"}'::jsonb),
  (null,3,165,'assess-leader-observation','Leader Observation Report','assessment','manual',false,true,'{"type": "📋 Assessment · Level 3 — Coach", "title": "Leader Observation Report", "body": "<h3>Purpose</h3>\n    <p>A monthly field observation report completed by a Coach after observing one of their leaders in action — in a Life Community meeting, a service, a one-on-one session, or a ministry event. The most real-world assessment in the pipeline.</p>\n    <h3>Observation Criteria</h3>\n    <ul>\n      <li>Group engagement: Did everyone participate, or just a few?</li>\n      <li>Biblical accuracy: Was the teaching sound and well-applied?</li>\n      <li>Relational warmth: Did the leader connect with people genuinely?</li>\n      <li>Facilitation skill: Did the leader guide without dominating?</li>\n      <li>EOLO culture: Did the leader invite members to think about their one person?</li>\n      <li>Multiplication mindset: Is the leader identifying and developing the next leader?</li>\n    </ul>\n    <h3>Process</h3>\n    <p>Coach observes quarterly (minimum). Report shared verbally in the next coaching conversation, with the written report filed in the leader''s pipeline record. Always begins with affirmation before growth points.</p>", "footer": "Your Church · Leader Observation Report · Quarterly minimum", "source": "multiply-template"}'::jsonb),
  (null,3,166,'assess-sermon-rubric','Sermon Evaluation Rubric','assessment','manual',false,true,'{"type": "📋 Assessment · Level 3 — Coach", "title": "Sermon Evaluation Rubric", "body": "<h3>Purpose</h3>\n    <p>A standardized tool for evaluating the preaching and teaching of Coach-level leaders, used after each observed message. Provides consistent, objective feedback that removes the subjectivity from preaching critique.</p>\n    <h3>Evaluation Categories</h3>\n    <ul>\n      <li><strong>Exegetical faithfulness (25%):</strong> Was the passage accurately interpreted and handled?</li>\n      <li><strong>Structure (20%):</strong> Was the sermon well-organized with a clear big idea?</li>\n      <li><strong>Illustrations (15%):</strong> Were illustrations relevant, clear, and culturally appropriate?</li>\n      <li><strong>Application (20%):</strong> Was the application specific, practical, and compelling?</li>\n      <li><strong>Delivery (20%):</strong> Voice, pace, eye contact, body language, engagement</li>\n    </ul>\n    <h3>Rating</h3>\n    <p>Each category: 1–5 scale. Total score out of 25. Score of 18+ considered \"ready for regular ministry.\" Score below 15 triggers an additional preaching coaching cycle before next opportunity.</p>", "footer": "Your Church · Sermon Evaluation Rubric · Used after each observed sermon", "source": "multiply-template"}'::jsonb),
  (null,3,167,'assess-teaching-practicum','Teaching Practicum Score','assessment','manual',false,true,'{"type": "📋 Assessment · Level 3 — Coach", "title": "Teaching Practicum Score", "body": "<h3>Purpose</h3>\n    <p>The formal evaluation of the Preaching Practicum (see training), resulting in a documented competency score that qualifies the leader for inclusion in the church''s teaching rotation.</p>\n    <h3>Scoring Breakdown</h3>\n    <ul>\n      <li>Session 1 (practice sermon, 10 min): 20% of total score</li>\n      <li>Session 2 (practice sermon, 20 min): 30% of total score</li>\n      <li>Session 3 (full sermon, live): 40% of total score</li>\n      <li>Peer evaluation component: 10% of total score</li>\n    </ul>\n    <h3>Qualification Threshold</h3>\n    <p>A score of 75% or above qualifies the leader for the church teaching rotation. A score of 85%+ qualifies for BTLI lecturing. Scores below 75% result in one additional coaching cycle and a repeat practicum opportunity.</p>", "footer": "Your Church · Teaching Practicum · Administered by Senior Pastor or designated Coach", "source": "multiply-template"}'::jsonb),
