-- ============================================================================
-- 060_pathway_catalog_seed.sql   ·   Session 58
-- Full-Unify (Path A): migrate the hand-authored leadership_pipeline.html into
-- pathway_rungs base so the diagram becomes data-driven + church-overlayable.
--
--   1. adds pathway_rungs.trackable (default true) — separates the member
--      progress spine (trackable) from the rich reference layer (trackable=false)
--   2. attaches the hand-authored MODALS detail to the 11 matching spine rungs
--   3. seeds 167 NEW base reference rungs (67 carry rich meta bodies; the rest are
--      titles the AI-research flow can enrich later)
--
-- The 37 spine keys from 057 are PRESERVED byte-for-byte (pathway_progress FKs
-- them by (level,rung_key) — renaming would orphan member progress). Merge is
-- high-confidence only: a static chip is folded into a spine rung ONLY when the
-- spine slug is a substring of the chip's modal key at the same level.
--
-- FLAT (#209), rerun-safe (on-conflict-do-nothing + if-not-exists, #210),
-- committed to migrations/ after running (#242/#252). church_id stays NULL (base);
-- pathway_rungs has no church-stamp trigger, and the SQL editor runs as owner.
-- Categories all satisfy pathway_rungs_category_check; levels satisfy 0..5.
-- ============================================================================

alter table public.pathway_rungs
  add column if not exists trackable boolean not null default true;


-- 2. attach hand-authored detail to matching TRACKABLE spine rungs -----------
update public.pathway_rungs set meta='{"type": "📚 Book · Level 5 — Executive Leader", "title": "Leading an Organization / Church", "body": "<h3>About This Book</h3>\n    <p>The sixth and final volume in Mac Lake''s <em>Leadership Pipeline</em> series addresses the unique challenges of leading an entire organization or church. It moves from departmental oversight to stewarding the whole — culture, vision, DNA, and succession.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>Casting and sustaining a God-given vision for the whole church</li>\n      <li>Guarding and transmitting organizational DNA across generations</li>\n      <li>Building a leadership culture, not just a leadership program</li>\n      <li>Managing the Leadership Pipeline from the top</li>\n      <li>Navigating the politics and pressures unique to senior leaders</li>\n      <li>Planning for succession before it''s urgent</li>\n    </ul>\n    <h3>Table of Contents (Sample Chapters)</h3>\n    <ul>\n      <li>1. The Weight of the Whole</li>\n      <li>2. Vision — Hearing, Holding, and Handing Off</li>\n      <li>3. Culture Eats Strategy for Breakfast</li>\n      <li>4. Managing the Pipeline from the Top</li>\n      <li>5. The Senior Leader''s Soul</li>\n      <li>6. Building a Board That Helps, Not Hurts</li>\n      <li>7. Succession: Your Greatest Act of Leadership</li>\n    </ul>\n    <h3>How to Use at This Level</h3>\n    <p>Read alongside a mentor or board member. Process each chapter with the question: \"What would this look like in our specific church context?\" Assign specific chapters to your Director-level leaders to create shared language.</p>", "footer": "Mac Lake · Multiply Group · multiply group.org", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=5 and rung_key='leading-org';
update public.pathway_rungs set meta='{"type": "🎯 Training · Level 5 — Executive Leader", "title": "IDC Church Planting Training", "body": "<h3>Overview</h3>\n    <p>The IDC (International Discipleship and Church Planting) church planting training is a comprehensive formation program for leaders sensing a call to plant a new church. It combines theological foundations, practical church planting methodology, and personal assessment.</p>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>Biblical theology of church planting</li>\n      <li>Personal calling assessment and church planter profile</li>\n      <li>Context exegesis — understanding your target community</li>\n      <li>The multiplication model: from house groups to full church</li>\n      <li>Leadership recruitment and team building for church plants</li>\n      <li>Financial planning and sustainability for a new church</li>\n      <li>Avoiding the most common church planting failures</li>\n      <li>Legal and organizational structures for new churches</li>\n    </ul>\n    <h3>Duration and Format</h3>\n    <p>Typically a multi-week intensive (varies by IDC cohort schedule). Includes mentoring from an experienced church planter, peer cohort learning, and field assignments in a real ministry context.</p>", "footer": "IDC · International Discipleship and Church Planting · idc.org.ph (verify link with Pastor)", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=5 and rung_key='plant';
update public.pathway_rungs set meta='{"type": "📚 Book · Level 4 — Director", "title": "Leading a Department / Ministry", "body": "<h3>About This Book</h3>\n    <p>The fifth book in Mac Lake''s series, focused on the unique challenges of leading a ministry department — managing a team of leaders, setting direction for a specific area, and aligning that area with the broader church mission.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>Transitioning from leading leaders to leading a whole department</li>\n      <li>Building a ministry department''s culture and systems</li>\n      <li>Strategic planning for a ministry area</li>\n      <li>Budget management in ministry contexts</li>\n      <li>Hiring, developing, and releasing volunteers and staff</li>\n      <li>Representing your department to senior leadership</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>1. The Scope Shift — What Changes at the Director Level</li>\n      <li>2. Owning the Vision for Your Ministry Area</li>\n      <li>3. Building Systems That Run Without You</li>\n      <li>4. Managing Your Team of Leaders</li>\n      <li>5. Budget and Resources in Ministry</li>\n      <li>6. Reporting Up: Working with Senior Leadership</li>\n      <li>7. Evaluating Ministry Effectiveness</li>\n    </ul>", "footer": "Mac Lake · Multiply Group · multiplygroup.org", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=4 and rung_key='leading-dept';
update public.pathway_rungs set meta='{"type": "📚 Book · Level 3 — Coach", "title": "Leading Leaders", "body": "<h3>About This Book</h3>\n    <p>The fourth volume in Mac Lake''s Leadership Pipeline series. It addresses the significant transition from leading a group of people to leading a team of leaders — one of the hardest shifts in any pipeline.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>Why leading leaders is harder than leading followers</li>\n      <li>The one-on-one coaching meeting as a leadership tool</li>\n      <li>Leading a huddle that sharpens other leaders</li>\n      <li>Providing feedback and evaluation</li>\n      <li>Encouraging leaders in ways that shape their souls</li>\n      <li>Making decisions that guard the mission and values</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>1. The Transition No One Tells You About</li>\n      <li>2. The One-on-One Meeting</li>\n      <li>3. Leading the Huddle</li>\n      <li>4. Feedback That Transforms</li>\n      <li>5. Encouraging the Leader''s Soul</li>\n      <li>6. Decision-Making at the Coach Level</li>\n    </ul>", "footer": "Mac Lake · Multiply Group · multiplygroup.org", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=3 and rung_key='leading-leaders';
update public.pathway_rungs set meta='{"type": "🎯 Training · Level 3 — Coach", "title": "APIIS Preachers Program", "body": "<h3>Overview</h3>\n    <p>The APIIS Preachers Program is a focused training track for those in or preparing for regular preaching and teaching ministry. It develops both the theological depth and the platform skills needed for effective biblical proclamation in the local church.</p>\n    <h3>Topics Covered</h3>\n    <ul>\n      <li>Principles of biblical interpretation (hermeneutics)</li>\n      <li>Expository preaching — from text to sermon</li>\n      <li>Topical and narrative preaching methodologies</li>\n      <li>Voice, delivery, and platform presence</li>\n      <li>Preaching to the Filipino cultural context</li>\n      <li>Application — making the Word land in real life</li>\n      <li>Preaching peer review and feedback practice</li>\n    </ul>\n    <h3>Qualification</h3>\n    <p>Completion of BTLI 103 and demonstration of basic teaching ability. Acceptance into the program requires recommendation from a Director or Pastor.</p>", "footer": "APIIS · Asia Pacific International Institute of Innovative Scholarship", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=3 and rung_key='apiis';
update public.pathway_rungs set meta='{"type": "📋 Assessment · Levels 3 & 4", "title": "CliftonStrengths Assessment", "body": "<h3>Overview</h3>\n    <p>Gallup''s CliftonStrengths (formerly StrengthsFinder) assessment identifies a person''s top 5 (or all 34) natural talent themes — the patterns of thought, feeling, and behavior that come most naturally to them and can be developed into genuine strengths.</p>\n    <h3>The 34 Themes (organized in 4 domains)</h3>\n    <ul>\n      <li><strong>Executing:</strong> Achiever, Arranger, Belief, Consistency, Deliberative, Discipline, Focus, Responsibility, Restorative</li>\n      <li><strong>Influencing:</strong> Activator, Command, Communication, Competition, Maximizer, Self-Assurance, Significance, Woo</li>\n      <li><strong>Relationship Building:</strong> Adaptability, Connectedness, Developer, Empathy, Harmony, Includer, Individualization, Positivity, Relational</li>\n      <li><strong>Strategic Thinking:</strong> Analytical, Context, Futuristic, Ideation, Input, Intellection, Learner, Strategic</li>\n    </ul>\n    <h3>Application in the Pipeline</h3>\n    <p>Results are debriefed in a 90-minute session with a CliftonStrengths-trained coach. The outcome: a strengths-based development plan that connects the person''s top themes to specific leadership competencies and ministry opportunities in the MULTIPLY pipeline.</p>", "footer": "Gallup · CliftonStrengths · gallup.com/cliftonstrengths", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=3 and rung_key='strengths';
update public.pathway_rungs set meta='{"type": "📚 Book · Level 2 — Leader", "title": "Leading Others", "body": "<h3>About This Book</h3>\n    <p>The third book in Mac Lake''s Leadership Pipeline series. It addresses the crucial transition from leading yourself to leading a small team or group — the most common leadership entry point in a local church.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The mindset shift from \"doing\" to \"leading\"</li>\n      <li>Mobilizing people toward a goal</li>\n      <li>Caring for people while getting things done</li>\n      <li>Delegating responsibility effectively</li>\n      <li>Confronting in love — the hardest skill of a new leader</li>\n      <li>Providing evaluation and encouragement</li>\n      <li>Situational leadership basics</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>1. You''re a Leader Now — Now What?</li>\n      <li>2. Mobilizing Your Team</li>\n      <li>3. Caring for the People You Lead</li>\n      <li>4. Delegating Without Abdicating</li>\n      <li>5. Confronting with Love</li>\n      <li>6. Evaluating and Encouraging</li>\n      <li>7. Solving Problems Before They Solve You</li>\n    </ul>", "footer": "Mac Lake · Multiply Group · multiplygroup.org", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=2 and rung_key='leading-others';
update public.pathway_rungs set meta='{"type": "📚 Book · Level 1 — Team Member", "title": "Leading Yourself", "body": "<h3>About This Book</h3>\n    <p>The second book in Mac Lake''s Leadership Pipeline series (the first addresses those not yet in any leadership). It introduces new believers and growing disciples to the foundational disciplines of self-leadership — the prerequisite for all other leadership.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>Learning the Word — personal Bible study habits</li>\n      <li>Following Jesus — daily surrender and discipleship</li>\n      <li>Loving the church — authentic community involvement</li>\n      <li>Serving others — moving from consumer to contributor</li>\n      <li>Sharing the gospel — the disciple''s witness</li>\n      <li>Multiplying disciples — the goal from day one</li>\n    </ul>\n    <h3>Table of Contents</h3>\n    <ul>\n      <li>1. Learning to Lead the Most Important Person — You</li>\n      <li>2. Learning the Word</li>\n      <li>3. Following Jesus Daily</li>\n      <li>4. Loving Your Church</li>\n      <li>5. Serving Others</li>\n      <li>6. Sharing the Gospel</li>\n      <li>7. The Goal: Multiplying Disciples</li>\n    </ul>\n    <h3>How to Use</h3>\n    <p>This is the primary text for new believers in discipleship. The discipler walks through one chapter per meeting with their disciple, using the reflection questions to drive personal application.</p>", "footer": "Mac Lake · Multiply Group · multiplygroup.org", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=1 and rung_key='leading-yourself';
update public.pathway_rungs set meta='{"type": "📚 Book · Level 0 — New Believer", "title": "Basic Christianity", "body": "<h3>About This Book</h3>\n    <p>John Stott''s respected classic for seekers and the newly converted — a thoughtful, gracious walk through the heart of the gospel: who Christ is, the reality of sin, what the cross accomplished, and how a person responds. Ideal for the pre-decision (Guest / Seeker) stage.</p>\n    <h3>Key Themes</h3>\n    <ul>\n      <li>The claims of Christ — who Jesus said He was</li>\n      <li>The human need — the reality of sin</li>\n      <li>The work of Christ — the meaning of the cross</li>\n      <li>The response — counting the cost and following</li>\n    </ul>\n    <h3>How to Use</h3>\n    <p>The EOLO Spiritual Friend reads this alongside a seeker before a decision, opening honest gospel conversations — without pressure.</p>", "footer": "John Stott · InterVarsity Press", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=0 and rung_key='basic-christianity';
update public.pathway_rungs set meta='{"type": "📋 Assessment · Level 0 — New Believer", "title": "Salvation Assurance Diagnostic", "body": "<h3>Purpose</h3>\n    <p>This diagnostic tool is designed to help a disciple and their discipler ascertain with a high level of certainty whether genuine saving faith has occurred — or whether there are unresolved questions that need to be addressed before the person proceeds further in the pipeline.</p>\n    <h3>Why This Is Necessary</h3>\n    <p>In the Philippine church context, many people have been baptized, attend church regularly, and even serve — without ever having made a genuine personal commitment to Christ. This diagnostic creates a safe, non-threatening space to explore that question honestly.</p>\n    <h3>Diagnostic Areas</h3>\n    <ul>\n      <li><strong>Knowledge:</strong> Can the person articulate the gospel accurately? (Who Jesus is, what sin is, what Christ did, what response is required)</li>\n      <li><strong>Testimony:</strong> Is there a credible testimony of repentance and faith? (Not necessarily dramatic — but genuine)</li>\n      <li><strong>Fruit:</strong> Is there evidence of the Spirit''s work? (Changed desires, love for God''s Word, genuine love for others, awareness of sin)</li>\n      <li><strong>Assurance:</strong> Does the person have genuine assurance of salvation? (Not presumption, not uncertainty — but confident faith based on God''s promises)</li>\n      <li><strong>1 John Test:</strong> A guided walk through 1 John''s six tests of genuine faith</li>\n    </ul>\n    <h3>Format</h3>\n    <p>Conducted as a one-on-one guided conversation with a trained discipler, not as a written exam. The discipler uses a structured set of open-ended questions. Duration: 60–90 minutes. Conducted before BTLI 101 and repeated at the Leader level transition.</p>\n    <h3>Outcomes</h3>\n    <ul>\n      <li><strong>Clear assurance:</strong> Proceed to BTLI 101 with confidence</li>\n      <li><strong>Genuine but uncertain:</strong> Additional sessions on assurance; use 1 John and Romans 8</li>\n      <li><strong>Unresolved:</strong> Present the gospel again; do not assume prior exposure = genuine response</li>\n    </ul>", "footer": "Your Church · Custom Diagnostic Tool · Confidential", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=0 and rung_key='salvation';
update public.pathway_rungs set meta='{"type": "🌱 Life Development · Level 1 — Team Member", "title": "Salvation Journal", "body": "<h3>Overview</h3>\n    <p>A simple, guided journal completed in the first 30 days of a new believer''s life in Christ — capturing their testimony, their first experiences with God, and their earliest prayers. Becomes a precious record of the beginning of their walk with Jesus.</p>\n    <h3>Journal Sections</h3>\n    <ul>\n      <li>My life before Christ — in my own words</li>\n      <li>The day/moment I said yes to Jesus</li>\n      <li>My first prayer as a believer</li>\n      <li>The first Bible verse that spoke to me</li>\n      <li>What I''m most grateful for</li>\n      <li>What I''m most afraid of as a new believer</li>\n      <li>A letter to my future self, one year from now</li>\n    </ul>\n    <h3>Purpose</h3>\n    <p>In moments of doubt or difficulty, new believers can return to this journal as a concrete reminder of what God did in their life. Also used in the Salvation Assurance Diagnostic as supporting evidence of genuine conversion.</p>", "footer": "Your Church · New Believer Welcome Kit", "source": "multiply-template"}'::jsonb, updated_at=now() where church_id is null and level=0 and rung_key='salvation';

-- 3. seed NEW base reference rungs (trackable=false) -------------------------
on conflict (level, rung_key) where church_id is null do nothing;

-- LEDGER (#212)
values ('060','060_pathway_catalog_seed.sql', now(),
        'Full-Unify: pathway_rungs.trackable column + attach hand-authored MODALS detail to 11 spine rungs + seed 167 reference rungs from leadership_pipeline.html')
on conflict (version) do nothing;

-- SELF-VERIFY (#210) — expect: trackable_col=1, base_total=204, ref_rungs=167,
--   spine_trackable=37, categories_ok=t
select
  (select count(*) from information_schema.columns where table_schema='public' and table_name='pathway_rungs' and column_name='trackable') as trackable_col,
  (select count(*) from public.pathway_rungs where church_id is null) as base_total,
  (select count(*) from public.pathway_rungs where church_id is null and trackable=false) as ref_rungs,
  (select count(*) from public.pathway_rungs where church_id is null and trackable=true) as spine_trackable,
  (select bool_and(category in ('book','training','lesson','ministry','coaching','assessment','character','competency','discipline')) from public.pathway_rungs where church_id is null) as categories_ok;
